210:     // Step through s
211:     const size_t step = f_len - sizeof(uint16_t) + 1;
212:     size_t s_i = f_len - sizeof(uint16_t);
213:     for (; s_i <= s_len - f_len; s_i += step) {
214:         size_t h;
215:         for (h = *(const uint16_t *)(s + s_i) % H_SIZE; h_table[h]; h = (h + 1) % H_SIZE) {
