421: int binary_search(const char *needle, char **haystack, int start, int end) {
422:     int mid;
423:     int rc;
424: 
425:     if (start == end) {
426:         return -1;
427:     }
428: 
429:     mid = start + ((end - start) / 2);
430: 
431:     rc = strcmp(needle, haystack[mid]);
432:     if (rc < 0) {
433:         return binary_search(needle, haystack, start, mid);
434:     } else if (rc > 0) {
435:         return binary_search(needle, haystack, mid + 1, end);
436:     }
437: 
438:     return mid;
439: }
