                // n is the last occupied index, so we have n+1 values
                case 'h':
                    if (m == '?') {
                        for (i = 0; i <= n; i++) {
                            switch (v[i]) {
                                case 3:
                                    GetConsoleScreenBufferInfo(stdo, &csbi);
                                    w = csbi.dwSize.X;
                                    h = csbi.srWindow.Bottom - csbi.srWindow.Top + 1;
                                    csize = w * (h + 1);
