                                        ((attr & BACKGROUND_MASK) >> 4);
                                    SetConsoleTextAttribute(stdo, attr);
                                    break;
                                case 9:
                                    break;
                                case 25:
                                    GetConsoleCursorInfo(stdo, &cci);
                                    cci.bVisible = TRUE;
                                    SetConsoleCursorInfo(stdo, &cci);
                                    break;
                                case 47:
                                    coord.X = 0;
                                    coord.Y = 0;
                                    SetConsoleCursorPosition(stdo, coord);
